OpenCV.Features.Correspondences.signature:
--  One candidate correspondence, copied exactly from a match and the
   --  stored keypoints of both feature sets.
   --  @field Query_Index One-based keypoint index in the Query set, copied
   --  from the match.
   --  @field Train_Index One-based keypoint index in the Train set, copied
   --  from the match.
   --  @field Query_Point Stored Position of the query keypoint, an exact
   --  Float32 copy in the query image's Region-local coordinates.
   --  @field Train_Point Stored Position of the train keypoint, an exact
   --  Float32 copy in the train image's Region-local coordinates.
   --  @field Distance Binary descriptor distance copied from the match. It
   --  is descriptor metadata, not a confidence, probability, geometric
   --  residual or reprojection error.
   type Point_Correspondence is record
      Query_Index : Positive;
      Train_Index : Positive;
      Query_Point : OpenCV.Float32_Point;
      Train_Point : OpenCV.Float32_Point;
      Distance    : Matching.Binary_Descriptor_Distance;
   end record;

OpenCV.Features.Matching.signature:
--  Exact integer binary descriptor distance: smaller means more similar.
   --  Hamming distances are in 0 .. 256 and Hamming_2 distances in 0 .. 128;
   --  the type range covers both. It is not a confidence or probability.
   type Binary_Descriptor_Distance is range 0 .. 256;

--  One accepted query/train descriptor pair.
   --  @field Query_Index One-based keypoint index in the Query feature set;
   --  native descriptor row Query_Index - 1.
   --  @field Train_Index One-based keypoint index in the Train feature set;
   --  native descriptor row Train_Index - 1.
   --  @field Distance Exact distance between the two descriptors under the
   --  sets' shared norm.
   type Descriptor_Match is record
      Query_Index : Positive;
      Train_Index : Positive;
      Distance    : Binary_Descriptor_Distance;
   end record;

--  One train neighbor of a query descriptor in a two-nearest result.
   --  @field Train_Index One-based keypoint index in the Train feature set.
   --  @field Distance Exact distance from the query descriptor to this train
   --  descriptor.
   type Binary_Neighbor is record
      Train_Index : Positive;
      Distance    : Binary_Descriptor_Distance;
   end record;

--  The two nearest train descriptors of one query descriptor.
   --  @field Query_Index One-based keypoint index in the Query feature set.
   --  @field Nearest Closest train neighbor.
   --  @field Second_Nearest Next closest train neighbor: its Train_Index
   --  differs from Nearest's and its Distance is at least Nearest.Distance.
   type Two_Nearest_Match is record
      Query_Index    : Positive;
      Nearest        : Binary_Neighbor;
      Second_Nearest : Binary_Neighbor;
   end record;

OpenCV.Features.signature:
--  Ordinary Ada array of keypoint values. Keypoints returns bounds
   --  1 .. Count, so element I corresponds to descriptor row I - 1.
   type Keypoint_Array is array (Positive range <>) of Keypoint;
